module.exports = function(RED) {
    function StartCampaignNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on('input', function(msg) {
            let numbers = [];

            if (Array.isArray(msg.payload)) numbers = msg.payload;
            else if (typeof msg.payload === 'string') numbers = [msg.payload];

            numbers.forEach(phone => {
                const newMsg = { 
                    ...msg,
                    phoneNumber: phone,
                    campaignId: `camp_${Date.now()}_${Math.random().toString(36).substr(2, 4)}`
                };
                node.send(newMsg);
            });

            node.status({ fill: "green", shape: "dot", text: numbers.length + " recipients" });
        });
    }
    RED.nodes.registerType("start-campaign", StartCampaignNode);
};